public Money parmTransactionCurrencyAmount(Money _transactionCurrencyAmount)
{
    if (abs(_transactionCurrencyAmount) < 0.01)
    {
        _transactionCurrencyAmount = round(_transactionCurrencyAmount, CurrencyDefaultPrecisionCache::getDefaultPrecisionFromEDT());
    }

    return next parmTransactionCurrencyAmount(_transactionCurrencyAmount);
}
